  "translations": {
    "L0001": "Je n’ai pas demandé à l’artisan de réparer l’horloge.",
    "L0002": "La boîte reposait près de la porte.",
    "L0003": "Il n’a remplacé que le cordon de la lampe.",
    "L0004": "J’ai demandé à l’artisan de ne pas réparer l’horloge.",
    "L0005": "À présent, la demande sonnait autrement.",
    "L0006": "L’horloge reposait toujours dans la boîte."
  },
